//! `bufferization` generated by `mlirformat tblgen` (`bufferization.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "bufferization.gen.rs"]
mod bufferization;

#[test]
fn bufferization_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<bufferization::Bufferization>();
    common::Fixtures::check_dialect(&opt, "bufferization");
}
